use std::sync::{Arc, Mutex};
use std::thread;

pub fn parallel_map<T, R, F>(items: Vec<T>, f: F, workers: usize) -> Vec<R>
where
    T: Send + 'static,
    R: Send + 'static,
    F: Fn(T) -> R + Send + Sync + 'static,
{
    let n = items.len();
    let f = Arc::new(f);
    let results: Arc<Mutex<Vec<Option<R>>>> =
        Arc::new(Mutex::new(vec![None; n]));

    // Work queue: (original index, item)
    let queue: Arc<Mutex<Vec<(usize, T)>>> =
        Arc::new(Mutex::new(items.into_iter().enumerate().collect()));

    let mut handles = Vec::with_capacity(workers);
    for _ in 0..workers {
        let queue = Arc::clone(&queue);
        let results = Arc::clone(&results);
        let f = Arc::clone(&f);

        let handle = thread::spawn(move || {
            loop {
                let job = {
                    let mut q = queue.lock().unwrap();
                    q.pop()
                };

                match job {
                    Some((idx, item)) => {
                        let result = f(item);
                        let mut r = results.lock().unwrap();
                        r[idx] = Some(result);
                    }
                    None => break,
                }
            }
        });

        handles.push(handle);
    }

    for handle in handles {
        handle.join().unwrap();
    }

    let final_results = results.lock().unwrap();
    final_results.into_iter().map(|opt| opt.unwrap()).collect()
}
