pub struct PairsMut<'a, T> {
    ptr: *mut T,
    len: usize,
    _marker: std::marker::PhantomData<&'a mut T>,
}

pub fn pairs_mut<T>(s: &mut [T]) -> PairsMut<'_, T> {
    PairsMut {
        ptr: s.as_mut_ptr(),
        len: s.len(),
        _marker: std::marker::PhantomData,
    }
}

impl<'a, T> Iterator for PairsMut<'a, T> {
    type Item = (&'a mut T, &'a mut T);

    fn next(&mut self) -> Option<Self::Item> {
        if self.len < 2 {
            return None;
        }
        let first = unsafe { &mut *self.ptr };
        let second = unsafe { &mut *self.ptr.offset(1) };
        self.ptr = unsafe { self.ptr.add(2) };
        self.len -= 2;
        Some((first, second))
    }
}
